import{z as i,x as s,o as t,c as B,q as E,j as o,D as e,d as r,s as n,S as A}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"工具整合推理 RL","description":"","frontmatter":{"title":"工具整合推理 RL","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/tool-integrated-rl.md","filePath":"llm/tool-integrated-rl.md","lastUpdated":1791063341000}'),p={name:"llm/tool-integrated-rl.md"};function d(m,a,h,_,D,T){const l=s("Mermaid");return t(),B("div",null,[a[2]||(a[2]=E('<h1 id="工具整合推理-rl" tabindex="-1">工具整合推理 RL <a class="header-anchor" href="#工具整合推理-rl" aria-label="Permalink to &quot;工具整合推理 RL&quot;">​</a></h1><div class="epigraph"><p>推理链里插入计算器、代码解释器或检索，奖励仍应钉在终局校验；工具只是动作，不是裁判。</p><footer>—— Gou 等 ToRA；Qwen2.5-Math 的工具集成；Kimi k1.5 / 后续推理模型的工具 RL</footer></div><p><a href="/llm/swe-rl-env">上一课</a>把工具循环用在修仓库。更轻的设定是：一道数学题，允许写代码、调计算器，最终答案仍走 <a href="/llm/math-verifier-equivalence">数学验证器</a>。缺口是：<strong>RL 会学会滥用工具刷格式或死循环调用，除非把调用代价与终局 \\(R\\) 一起写进目标。</strong> ToRA 等用 SFT 示范工具轨迹；本课写接到 <a href="/llm/grpo">GRPO</a> 时多出来的动作。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>纯文本 CoT 在算术上易算错。工具把可靠计算外包。策略要学：何时调、调什么、如何把返回写回链。SFT 示范有限。RL 用终局对错可以学到示范外的调用策略。失败模式：每步都调工具（费用爆炸）、忽略返回继续幻觉、构造使解释器报错的调用骗过「尝试过」塑形。</p><p><span class="marginnote">直觉类比：RL 像一位只看期末分数的老师。若「平时举手次数」也算分，学生就会疯狂举手不答题——这正是「调用次数当奖励」的下场。只有期末对错算分，学生才会去琢磨什么时候举手真的有用。</span></p><p>\\(R\\) 必须是终局答案等价，最多加很轻的格式项。不要用「成功调用次数」当主奖励。调用日志是状态，不是分数。</p>',7)),(t(),o(A,null,{default:e(()=>[n(l,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E7%AD%96%E7%95%A5%E5%AD%A6%E4%BC%9A%E8%B0%83%E7%94%A8%22%5D%20--%3E%20F1%5B%22%E6%AF%8F%E6%AD%A5%E9%83%BD%E8%B0%83%EF%BC%9A%E8%B4%B9%E7%94%A8%E7%88%86%E7%82%B8%22%5D%0A%20%20S%20--%3E%20F2%5B%22%E5%BF%BD%E7%95%A5%E8%BF%94%E5%9B%9E%EF%BC%9A%E7%BB%A7%E7%BB%AD%E5%B9%BB%E8%A7%89%22%5D%0A%20%20S%20--%3E%20F3%5B%22%E6%9E%84%E9%80%A0%E6%8A%A5%E9%94%99%E8%B0%83%E7%94%A8%E9%AA%97%E8%BF%87%E5%A1%91%E5%BD%A2%22%5D%0A%20%20F1%20--%3E%20D1%5B%22%E8%B0%83%E7%94%A8%E6%AC%A1%E6%95%B0%E8%BD%AF%E6%83%A9%E7%BD%9A%22%5D%0A%20%20F2%20--%3E%20D2%5B%22%E7%BB%88%E5%B1%80%E7%AD%89%E4%BB%B7%20R%20%E6%A0%A1%E9%AA%8C%22%5D%0A%20%20F3%20--%3E%20D3%5B%22%E7%8E%AF%E5%A2%83%20token%20mask%20%E5%87%BA%E6%8D%9F%E5%A4%B1%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E('<h3 id="工具输出是环境-不是模型-token-的对数概率" tabindex="-1">工具输出是环境，不是模型 token 的对数概率 <a class="header-anchor" href="#工具输出是环境-不是模型-token-的对数概率" aria-label="Permalink to &quot;工具输出是环境，不是模型 token 的对数概率&quot;">​</a></h3><p>解释器返回应 mask 掉策略损失，或标为环境 token，否则模型学习模仿数字的表面形式而不是调用。这与 SFT 仅回复损失同一逻辑，RL 里更易忘。</p><p><span class="marginnote">「mask 掉」就是这些 token 不算进策略的损失。解释器打印的数字是环境给的，不是模型选的；若不 mask，模型会被训练去「预测计算结果」，学的是模仿输出的表面形状，而不是学会何时该调用计算器。</span></p><p><span class="marginnote">检索工具的 \\(R\\) 更脏：文档是否支持答案难以程序化，接近开放域，需细则或人类。本课主场是代码解释器 + 数学终局。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>动作空间：普通 token + 特殊调用块。环境执行，把 stdout 写回上下文。轨迹结束抽答案，等价判定得 \\(R\\)。组采样时每条轨迹独立工具沙箱。PPO 对调用块内外都算比率，但环境 token 的 \\(\\pi\\) 不定义，必须 mask。代价：对调用次数软惩罚，与过长过滤并列。</p>',6)),(t(),o(A,null,{default:e(()=>[n(l,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20COT%5B%22%E6%80%9D%E7%BB%B4%20token%22%5D%20--%3E%20CALL%5B%22%E8%B0%83%E7%94%A8%E8%A7%A3%E9%87%8A%E5%99%A8%22%5D%0A%20%20CALL%20--%3E%20ENV%5B%22%E6%89%A7%E8%A1%8C%EF%BC%8C%E8%BF%94%E5%9B%9E%20stdout%22%5D%0A%20%20ENV%20--%3E%20COT%0A%20%20COT%20--%3E%20ANS%5B%22%E6%9C%80%E7%BB%88%E7%AD%94%E6%A1%88%22%5D%0A%20%20ANS%20--%3E%20EQ%5B%22%E7%AD%89%E4%BB%B7%E6%A0%A1%E9%AA%8C%20R%22%5D%0A%20%20EQ%20--%3E%20GRPO%5B%22%E7%BB%84%E7%9B%B8%E5%AF%B9%E6%9B%B4%E6%96%B0%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=E('<p>与过程监督：工具轨迹的逐步合法可用「代码是否运行」当稀疏过程信号，仍不要替代终局等价。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>工具降低算术噪声，使 \\(R\\) 更接近「是否会列式」，RL 优化的是规划。过优化表现为：用代码暴力枚举、超时边缘、或输出恰好让抽取器高兴的打印格式。沙箱时限与内存属于 \\(R\\) 规范。无 KL 时，模型更敢发明奇怪调用，需要过长与过调用过滤。</p><p><span class="marginnote">为什么重要：若训练沙箱不限时，模型会学会「跑十分钟暴力枚举」这种解法；上线时限 5 秒，策略立刻失灵。时限与内存上限要当作奖励定义的一部分来设计，而不是事后再补的工程细节。</span></p><p><span class="marginnote">训练-推理工具版本必须一致。解释器库差一个小数，等价判定会漂。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>没有解释器的部署不能用训时依赖工具的策略，或要有纯文本回退。SWE 环境更重，本课是单题工具。下一课把算力、步数、准确率收成 RL 缩放，问加更多 RL 是否永远有回报。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>工具是动作，终局 \\(R\\) 仍是校验器；调用次数不能当主奖励。</li><li>环境返回 token 必须从策略损失里 mask。</li><li>防死循环与暴力枚举：时限、调用惩罚、与训练一致的沙箱。</li><li>主场：代码解释器 + 数学等价；检索更脏。</li><li>出处：Gou 等 ToRA；Qwen2.5-Math TIR；DeepSeek-AI / Kimi 推理模型的工具使用；校验器见 DeepSeekMath。</li></ul>',9))])}const u=i(p,[["render",d]]);export{c as __pageData,u as default};
